#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <set>
#include <string>
#include <random>
using namespace std;

int main(){
vector<double> x={1,2,3,4},y={2,4,6,8};
double weight=1,mean=0,variance=0;
vector<double> gradients;
for(int i=0;i<int(x.size());i++){
    double gradient=2*(weight*x[i]-y[i])*x[i];
    gradients.push_back(gradient);
    mean+=gradient/x.size();
}
for(double gradient:gradients)variance+=pow(gradient-mean,2)/gradients.size();
cout<<"Full gradient "<<mean<<" SGD variance "<<variance<<endl;
    return 0;
}

