#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <set>
#include <string>
#include <random>
using namespace std;

int main(){
vector<int> bin={0,0,1,1,2,2};
vector<double> gradient={-1,-2,1,0,-2,1};
vector<double> hessian={1,1,1,1,1,1};
double totalGradient=0,totalHessian=0;
for(int i=0;i<int(bin.size());i++){
    totalGradient+=gradient[i];totalHessian+=hessian[i];
}
double leftGradient=0,leftHessian=0,lambda=1;
for(int split=0;split<2;split++){
    for(int i=0;i<int(bin.size());i++)if(bin[i]==split){
        leftGradient+=gradient[i];leftHessian+=hessian[i];
    }
    double rightGradient=totalGradient-leftGradient;
    double rightHessian=totalHessian-leftHessian;
    double gain=0.5*(leftGradient*leftGradient/(leftHessian+lambda)
        +rightGradient*rightGradient/(rightHessian+lambda)
        -totalGradient*totalGradient/(totalHessian+lambda));
    cout<<"Split "<<split<<" gain "<<gain<<endl;
}
    return 0;
}

