for(int i=0;i<int(x.size());i++){
    double score=bias;
    for(int j=0;j<int(weight.size());j++)score+=weight[j]*x[i][j];
    double margin=label[i]*score;
    smallest=min(smallest,margin);
    cout<<"Sample "<<i<<" margin "<<margin<<endl;
}
cout<<"Functional margin "<<smallest<<endl;
    return 0;
}

