#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <set>
#include <string>
#include <random>
using namespace std;

int main(){
vector<double> score={0.9,0.8,0.5,0.4,0.2};
vector<int> label={1,0,1,0,1};
for(double cutoff:{0.3,0.6,0.85}){
    int tp=0,fp=0,fn=0;
    for(int i=0;i<int(score.size());i++){
        bool positive=score[i]>=cutoff;
        if(positive&&label[i])tp++;
        if(positive&&!label[i])fp++;
        if(!positive&&label[i])fn++;
    }
    double precision=tp+fp?double(tp)/(tp+fp):0;
    double recall=tp+fn?double(tp)/(tp+fn):0;
    double f1=precision+recall?2*precision*recall/(precision+recall):0;
    cout<<cutoff<<" "<<precision<<" "<<recall<<" "<<f1<<endl;
}
    return 0;
}

