#include <algorithm>
#include <cmath>
#include <iomanip>
#include <set>
#include <string>
#include <random>
using namespace std;

int main(){
vector<double> a={10,10,30,30},b={20,15,40,35};
double left=max(a[0],b[0]),top=max(a[1],b[1]);
double right=min(a[2],b[2]),bottom=min(a[3],b[3]);
double intersection=max(0.0,right-left)*max(0.0,bottom-top);
double areaA=(a[2]-a[0])*(a[3]-a[1]);
double areaB=(b[2]-b[0])*(b[3]-b[1]);
if(areaA<=0||areaB<=0)return 1;
double iou=intersection/(areaA+areaB-intersection);
cout<<"IoU "<<iou<<endl;
    return 0;
}

